  app.innerHTML = `<div class="login-layout"><section class="login-hero"><div class="brand-lockup">${icon('bot',35)}<div><b>AI Workbench</b><span>企业 AI 智能体工作台</span></div></div><div class="hero-copy"><h1>让 AI 成为<br>每一位团队成员的<span>创造力引擎</span></h1><p>在 AI 的陪伴下，激发灵感，高效创作，共同成长</p><div class="hero-values"><span>${icon('zap')} 高效创作</span><span>${icon('users')} 协同共建</span><span>${icon('book-open')} 专业可信</span></div></div></section><section class="login-side"><nav class="login-links">产品官网　 |　 帮助中心　 |　 下载客户端</nav><form class="login-card" id="login"><div class="brand-lockup small">${icon('bot',28)}<div><b>AI Workbench</b><span>企业 AI 智能体工作台</span></div></div><h2>欢迎登录 AI Workbench</h2><p>开启高效、智能、协同的创作新体验</p><div class="tab-row"><button type="button" class="active">账号登录</button><button type="button" disabled>验证码登录</button></div><label><span>账号</span><input name="account" type="email" required autocomplete="username" placeholder="请输入账号 / 邮箱"></label><label><span>密码</span><input name="password" type="password" required autocomplete="current-password" placeholder="请输入密码"></label><div class="form-row"><label class="checkbox"><input type="checkbox" checked> 记住我</label><button type="button" class="link-button" disabled>忘记密码？</button></div><button class="button primary full" type="submit">登 录</button><p class="form-error" role="alert"></p><p class="login-disabled">微信、钉钉、企业微信登录即将支持</p></form></section></div>`;
  document.querySelector('.login-links').innerHTML = '<button type="button" class="login-help" id="login-help">帮助中心</button>';
  document.querySelector('#login-help').onclick = showHelpDialog;
  document.querySelector('.login-disabled')?.remove();
  document.querySelector('#login').onsubmit = async e => { e.preventDefault(); const err = document.querySelector('.form-error'); try { await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}); boot(); } catch (error) { err.textContent = error.message; } };
  refreshIcons();
