const baseNavs = [['workspace','layout-dashboard','工作台'],['image','wand-sparkles','AI 创作'],['history','history','历史记录'],['generations','folder-open','我的生成'],['knowledge','book-open','知识库'],['assets','image','素材库'],['members','users','成员管理'],['enterprise','settings','企业设置'],['profile','user-round','个人中心']];
const pageRoutes = Object.freeze({workspace:'/workspace',image:'/agents/image',copywriting:'/agents/copywriting',campaign:'/agents/campaign',history:'/conversations',generations:'/generations',knowledge:'/knowledge',assets:'/assets',enterprise:'/enterprise-config','platform-skills':'/platform/skills'});
const pageFromPath = path => Object.entries(pageRoutes).find(([,route])=>route===path)?.[0]||null;
const navigationState = page => ({page,activeAgentId,activeConversationId});
const allowedPage = page => page==='platform-skills'&&!me?.is_platform_admin?'workspace':page;
function navigate(page,{replace=false}={}){
  const target=allowedPage(page),path=pageRoutes[target]||location.pathname,state=navigationState(target),current=window.history.state||{};
  const same=location.pathname===path&&current.page===state.page&&current.activeAgentId===state.activeAgentId&&current.activeConversationId===state.activeConversationId;
  window.history[replace||same?'replaceState':'pushState'](state,'',path);
  return render(target);
}
function pageFromNavigation(state=window.history.state){
  const page=allowedPage(state?.page||pageFromPath(location.pathname)||'workspace');
  if(state&&Object.prototype.hasOwnProperty.call(state,'activeAgentId'))activeAgentId=state.activeAgentId||'image-agent';
  if(state&&Object.prototype.hasOwnProperty.call(state,'activeConversationId'))activeConversationId=state.activeConversationId||null;
  return page;
}
window.addEventListener('popstate',event=>{if(me)render(pageFromNavigation(event.state));});
const roleName = role => role === 'enterprise_admin' ? '企业管理员' : '成员';
function shell(initialPage = 'workspace') {
  const navs = me.is_platform_admin ? [...baseNavs.slice(0,-1),['platform-skills','package-check','Skill 管理'],baseNavs.at(-1)] : baseNavs;
  app.innerHTML = `<div class="app-shell"><aside class="sidebar"><div class="brand-lockup">${icon('bot',30)}<div><b>AI Workbench</b><span>Create · Collaborate · Grow</span></div></div><button class="tenant-switch" aria-label="切换企业（当前不可用）" disabled>${icon('building-2')}<span><b>${escapeHtml(me.tenant_name || me.tenant_id || '企业工作台')}</b><small>${me.is_platform_admin?'平台管理':'企业版'}</small></span>${icon('chevron-down',16)}</button><nav class="side-nav">${navs.map(([id,i,label]) => `<button data-page="${id}">${icon(i)}<span>${label}</span></button>`).join('')}</nav><section class="side-credit" id="side-credit"></section><div class="side-user"><span class="avatar side-avatar">${escapeHtml((me.display_name||'我')[0])}</span><span><b>${escapeHtml(me.display_name)}</b><small>${me.is_platform_admin?'平台管理员':roleName(me.role)}</small></span><button aria-label="更多操作（暂未开放）" disabled>${icon('ellipsis',18)}</button></div></aside><main class="shell-main"><header class="topbar"><label class="global-search global-search-disabled" aria-disabled="true" title="全局搜索暂未开放">${icon('search')}<input aria-label="全局搜索暂未开放" placeholder="全局搜索暂未开放" disabled><kbd>Ctrl K</kbd></label><div class="top-actions"><button class="top-icon" aria-label="通知（暂未开放）" disabled>${icon('bell')}</button><button class="top-icon" id="top-help" aria-label="帮助与反馈">${icon('circle-help')}</button><div class="account-menu-wrap" id="account-menu-wrap"><button class="account-trigger" id="account-trigger" aria-haspopup="menu" aria-expanded="false"><span class="avatar">${escapeHtml((me.display_name||'我')[0])}</span><b>${escapeHtml(me.display_name)}</b>${icon('chevron-down',16)}</button><div class="account-dropdown" id="account-dropdown" role="menu" hidden><div class="account-summary"><span class="avatar account-avatar">${escapeHtml((me.display_name||'我')[0])}</span><div><b>${escapeHtml(me.display_name)}</b><small class="role-badge">${me.is_platform_admin?'平台管理员':roleName(me.role)}</small><em>${escapeHtml(me.tenant_name || me.tenant_id || '企业工作台')}</em></div></div><div class="account-menu-group"><button role="menuitem" data-account-action="profile">${icon('user-round')}个人中心</button><button role="menuitem" data-account-action="security">${icon('shield-check')}账号与安全</button><button role="menuitem" data-account-action="help">${icon('circle-help')}帮助与反馈</button></div><div class="account-menu-divider"></div><button role="menuitem" class="account-logout" data-account-action="logout">${icon('log-out')}退出登录</button></div></div></div></header><section class="page" id="main"></section></main></div>`;
  document.querySelectorAll('[data-page]').forEach(x => x.onclick = () => navigate(x.dataset.page));
  document.querySelector('#top-help').onclick = showHelpDialog;
  bindAccountMenu();
  syncAvatarViews(); render(initialPage); refreshIcons();
}

const header = (title, description, iconName) => `<header class="page-header"><div class="title-row">${icon(iconName,32)}<div><h1>${title === '企业配置' ? '企业设置' : title}</h1><p>${description}</p></div></div></header>`;
const button = (copy, iconName, cls='secondary', attrs='') => `<button type="button" class="button ${cls}" ${attrs}>${icon(iconName,17)}${copy}</button>`;
const stageMap = {queued:'正在理解需求',loading_context:'正在读取企业资料',retrieving_knowledge:'正在读取企业资料',retrieving_assets:'正在准备品牌素材',generating:'正在生成图片',saving_asset:'正在保存结果'};
const pageLoading = () => `<section class="page-loading" aria-live="polite" aria-busy="true"><div class="skeleton-title"><i></i><span></span></div><div class="skeleton-subtitle"></div><div class="skeleton-layout"><article><div class="skeleton-banner"></div><div class="skeleton-row"><i></i><i></i><i></i></div><div class="skeleton-panel"></div></article><aside><div class="skeleton-card"></div><div class="skeleton-card"></div></aside></div><p>正在加载页面内容…</p></section>`;

async function render(page) {
  const main = document.querySelector('#main');
  main.dataset.page = page;
  document.querySelectorAll('[data-page]').forEach(x => x.classList.toggle('active',x.dataset.page === page));
  main.innerHTML = pageLoading();
  try {
    if (page === 'workspace') return await workspaceV2(main);
    if (page === 'image') return await agentWorkspaceV2(main,'image-agent');
    if (page === 'copywriting') return await agentWorkspaceV2(main,'copywriting-agent');
    if (page === 'campaign') return await agentWorkspaceV2(main,'campaign-agent');
    if (page === 'history') return await conversationHistory(main);
    if (page === 'generations') return await generations(main);
    if (page === 'knowledge') return await knowledgeV2(main);
    if (page === 'assets') return await assets(main);
    if (page === 'enterprise') return await enterprise(main);
    if (page === 'members') return await members(main);
    if (page === 'billing') return await billing(main);
    if (page === 'profile') return await profileV2(main);
    if (page === 'platform-skills' && me.is_platform_admin) return await platformSkills(main);
  } catch (error) { main.innerHTML = `<section class="page-load-error" role="alert"><b>${icon('circle-alert',24)}页面加载失败</b><p>${escapeHtml(error.message || '请稍后重试。')}</p><button class="button primary" data-retry-page="${escapeHtml(page)}">${icon('refresh-cw')}重新加载</button></section>`; main.querySelector('[data-retry-page]').onclick = () => render(page); refreshIcons(); }
}

